/**
 * The DOM rendering of the event creator — form controls, preview, and delivery.
 *
 * All behaviour comes from `useEventCreator`; this file owns markup only, so the
 * embed, the hosted site, and any third-party host share identical form logic.
 */

import { useEffect, useMemo, useState } from 'react';
import {
  LIMITS,
  type EventDraft,
  type EventFormatId,
  type EventRecurrence,
  type EventShowAs,
  type RecurrenceFrequency,
} from '@project/event-format';
import {
  type EventExport,
  durationPartsToMinutes,
  eventDurationMinutes,
  groupTimeZones,
  listTimeZones,
  splitDurationMinutes,
  timeZoneLabel,
  useEventCreator,
  withTimeZone,
} from '@project/event-creator';

import { DescribeEvent, type ProposeDraft } from './DescribeEvent';
import { eventRecap } from './recap';
import { copyExport, downloadExport, localTimeZone, nextHalfHour, todayLocal } from './download';
import { ensureEventCreatorStyles } from './styles';

export interface EventCreatorProps {
  /** Start from an existing event — an edit, a host prefill, or an AI-proposed draft. */
  readonly initialDraft?: EventDraft;
  readonly defaultDate?: string;
  readonly defaultTimeZone?: string;
  readonly defaultFormat?: EventFormatId;
  /** Hide the live format preview (embeds are often tight on space). */
  readonly showPreview?: boolean;
  /** Called after a successful export, before the file is delivered. */
  readonly onExport?: (payload: EventExport) => void;
  /** Skip the built-in download so a host can deliver the file its own way. */
  readonly deliver?: (payload: EventExport) => void;
  /**
   * Turn free text into a draft. Supplying it shows the "describe it" box; the host owns the
   * transport, so this package never holds a model, a key, or an endpoint.
   */
  readonly propose?: ProposeDraft;
}

/**
 * The alert ladder from Apple Calendar, in minutes before the start. "At time of event" is 0 —
 * the chip set this replaced could not say it at all, and it is the one people reach for on a
 * reminder-style event.
 */
const ALERT_CHOICES = [0, 5, 10, 15, 30, 60, 120, 1440, 2880, 10080] as const;
const FREQUENCIES: readonly RecurrenceFrequency[] = ['daily', 'weekly', 'monthly', 'yearly'];

/**
 * Apple's repeat menu, which puts the common intervals in the list instead of behind a number
 * field: "Every 2 Weeks" is one tap, and anything else goes to Custom. Same rules underneath —
 * a preset is just a frequency and an interval.
 */
const REPEAT_PRESETS = [
  { id: 'never', label: 'Never' },
  { id: 'daily', label: 'Every day', frequency: 'daily', interval: 1 },
  { id: 'weekly', label: 'Every week', frequency: 'weekly', interval: 1 },
  { id: 'biweekly', label: 'Every 2 weeks', frequency: 'weekly', interval: 2 },
  { id: 'monthly', label: 'Every month', frequency: 'monthly', interval: 1 },
  { id: 'yearly', label: 'Every year', frequency: 'yearly', interval: 1 },
  { id: 'custom', label: 'Custom…' },
] as const;

function alertLabel(minutes: number): string {
  if (minutes === 0) return 'At time of event';
  if (minutes < 60) return `${minutes} minutes before`;
  if (minutes < 1440) return `${minutes / 60} ${minutes === 60 ? 'hour' : 'hours'} before`;
  if (minutes < 10080) return `${minutes / 1440} ${minutes === 1440 ? 'day' : 'days'} before`;
  return `${minutes / 10080} week before`;
}

/** "Alert", then "Second alert" — Apple's wording, and a sensible fallback past its two. */
const ALERT_LABELS = ['Alert', 'Second alert', 'Third alert', 'Fourth alert', 'Fifth alert'];
const alertRowLabel = (index: number): string => ALERT_LABELS[index] ?? `Alert ${index + 1}`;

/** Which entry in the repeat menu a rule corresponds to, or 'custom' when none of them fit. */
function presetFor(recurrence: EventRecurrence | undefined): string {
  if (recurrence === undefined) return 'never';
  const interval = recurrence.interval ?? 1;
  const match = REPEAT_PRESETS.find(
    (preset) =>
      'frequency' in preset &&
      preset.frequency === recurrence.frequency &&
      preset.interval === interval,
  );
  return match?.id ?? 'custom';
}

/** What an interval counts, so "Every 2 …" reads as a sentence rather than a spec. */
const INTERVAL_UNIT: Record<RecurrenceFrequency, string> = {
  daily: 'days',
  weekly: 'weeks',
  monthly: 'months',
  yearly: 'years',
};

/**
 * The duration boxes, largest first. An all-day event shows Days alone — the other two have no
 * meaning for it, since the file it produces carries dates and no clock.
 */
const DURATION_UNITS = [
  { key: 'days', label: 'Days' },
  { key: 'hours', label: 'Hours' },
  { key: 'minutes', label: 'Minutes' },
] as const;

type DurationUnit = (typeof DURATION_UNITS)[number]['key'];
type DurationFields = Record<DurationUnit, string>;

/** The draft's duration as field contents; empty boxes when there is no end to measure to. */
function asFields(minutes: number | null): DurationFields {
  if (minutes === null) return { days: '', hours: '', minutes: '' };
  const parts = splitDurationMinutes(minutes);
  return {
    days: String(parts.days),
    hours: String(parts.hours),
    minutes: String(parts.minutes),
  };
}

/** A repeat runs forever, a set number of times, or up to a date — never two of those. */
type RepeatEnd = 'never' | 'count' | 'until';

function withoutEnd(recurrence: EventRecurrence): EventRecurrence {
  return {
    frequency: recurrence.frequency,
    ...(recurrence.interval === undefined ? {} : { interval: recurrence.interval }),
  };
}

/** Says the rule back in a sentence: nobody should have to read RRULE to check their event. */
function repeatSummary(recurrence: EventRecurrence): string {
  const every =
    recurrence.interval === undefined || recurrence.interval === 1
      ? { daily: 'Every day', weekly: 'Every week', monthly: 'Every month', yearly: 'Every year' }[
          recurrence.frequency
        ]
      : `Every ${recurrence.interval} ${INTERVAL_UNIT[recurrence.frequency]}`;
  if (recurrence.count !== undefined) return `${every}, ${recurrence.count} times.`;
  if (recurrence.until !== undefined && recurrence.until !== '')
    return `${every}, until ${recurrence.until}.`;
  return `${every}, with no end — your calendar can stop it later.`;
}

export function EventCreator(props: EventCreatorProps): React.JSX.Element {
  const { showPreview = true } = props;
  useEffect(() => ensureEventCreatorStyles(), []);

  // Only today gets the next half hour. On any other date there is no "now" to be later than,
  // and 09:00 is the better guess for a thing being planned.
  const openingDate = props.defaultDate ?? todayLocal();
  const creator = useEventCreator({
    defaults: {
      date: openingDate,
      ...(openingDate === todayLocal() ? { clock: nextHalfHour() } : {}),
      // No zone unless the host names one. A zone is a claim about the event, not about the
      // person filling the form: "9am" typed on a laptop in Berlin usually means 9am wherever
      // the event happens, and a zone-less event does exactly that in every calendar. The
      // browser's zone is still one tap away — it's the first option in the picker.
      ...(props.defaultTimeZone === undefined ? {} : { timeZone: props.defaultTimeZone }),
      ...(props.defaultFormat === undefined ? {} : { formatId: props.defaultFormat }),
    },
    ...(props.initialDraft === undefined ? {} : { initialDraft: props.initialDraft }),
  });

  const { draft, dispatch, problemFor } = creator;
  // The picker must offer whatever the draft already carries, even a zone this runtime doesn't
  // enumerate — otherwise touching the field would silently rewrite the event's zone.
  const zoneGroups = useMemo(
    () => groupTimeZones(withTimeZone(creator.state.timeZone, listTimeZones())),
    [creator.state.timeZone],
  );
  const browserZone = useMemo(() => localTimeZone(), []);
  const allDay = draft.start.kind === 'date';
  const recurrence = draft.recurrence;
  const repeatEnd: RepeatEnd =
    recurrence?.count !== undefined ? 'count' : recurrence?.until !== undefined ? 'until' : 'never';
  const setRecurrence = (value: EventRecurrence | undefined): void =>
    dispatch({ type: 'set-recurrence', value });
  const [attendee, setAttendee] = useState('');
  const [copied, setCopied] = useState(false);
  // Sticky, because a custom rule can happen to match a preset — "every 1 week" is a weekly
  // event — and the custom controls disappearing mid-edit would be baffling.
  const [customRepeat, setCustomRepeat] = useState(false);
  const repeatPreset = customRepeat && recurrence !== undefined ? 'custom' : presetFor(recurrence);
  const alerts = draft.remindersMinutesBefore ?? [];
  // One row per alert, plus an empty one to add the next — so the first render shows a single
  // "Alert" row and a second appears only once the first is set, the way Apple's sheet does.
  const alertRows = alerts.length < LIMITS.reminders ? [...alerts, undefined] : [...alerts];
  const endZone = draft.end?.kind === 'dateTime' ? draft.end.timeZone : undefined;
  // Sticky like the custom repeat: choosing the same zone on both sides must not fold the second
  // control away underneath someone who is still choosing.
  const [splitZonesChosen, setSplitZones] = useState(false);
  const splitZones =
    splitZonesChosen || (endZone !== undefined && endZone !== creator.state.timeZone);

  /* Every option stays short on purpose. WebKit sizes the control by its widest option and leaks
     that width into the layout around it — a 36-character option ("America/Los_Angeles (your time
     zone)") pushed a 320px page into horizontal scroll. The detail lives in the hint below, where
     a sentence costs nothing. Shared by both zone selects, which must offer the same list. */
  const zoneOptions = (
    <>
      <option value="">No time zone</option>
      {browserZone !== undefined && (
        <optgroup label="Yours">
          <option value={browserZone}>{timeZoneLabel(browserZone)}</option>
        </optgroup>
      )}
      <option value="UTC">UTC</option>
      {zoneGroups.map((group) => (
        <optgroup key={group.region} label={group.region}>
          {group.zones.map((zone) => (
            <option key={zone} value={zone}>
              {timeZoneLabel(zone)}
            </option>
          ))}
        </optgroup>
      ))}
    </>
  );

  const startDate =
    draft.start.kind === 'date' ? draft.start.date : draft.start.dateTime.slice(0, 10);
  const startTime = draft.start.kind === 'date' ? '' : draft.start.dateTime.slice(11, 16);
  const end = draft.end;
  const endDate =
    end === undefined ? '' : end.kind === 'date' ? end.date : end.dateTime.slice(0, 10);
  const endTime = end === undefined || end.kind === 'date' ? '' : end.dateTime.slice(11, 16);

  // The duration is the draft's, not a second copy of it — it recomputes whenever either end
  // moves. The typed values exist only while someone is filling the boxes in: the draft's own
  // split carries (26 hours becomes 1 day, 2 hours), and doing that mid-keystroke would move the
  // number out from under the cursor. All three are held together, or the carry would land in
  // Days while Hours still showed the 26 that caused it.
  const duration = eventDurationMinutes(draft);
  const [typedDuration, setTypedDuration] = useState<DurationFields | null>(null);
  const durationFields = typedDuration ?? asFields(duration);
  const setDurationField = (key: DurationUnit, value: string): void => {
    const next = { ...durationFields, [key]: value };
    setTypedDuration(next);
    const minutes = durationPartsToMinutes(next);
    // Boxes that don't add up to a duration leave the event alone; they keep showing what was
    // typed until they do, or until the field is handed back.
    if (minutes !== null) dispatch({ type: 'set-duration', minutes });
  };

  const submit = (event: React.FormEvent): void => {
    event.preventDefault();
    const result = creator.requestExport();
    if (!result.ok) return;
    props.onExport?.(result.export);
    (props.deliver ?? downloadExport)(result.export);
  };

  const addAttendee = (): void => {
    const email = attendee.trim();
    if (email === '') return;
    dispatch({ type: 'add-attendee', value: { email } });
    setAttendee('');
  };

  /**
   * The mark beside a label whose field must hold something before the event will export.
   *
   * Only five of the fourteen controls qualify, and they are the five that open pre-filled — so
   * this is less an instruction than a warning about what not to clear. It is `aria-hidden`
   * because the input carries `required`, which is what a screen reader announces; a spoken
   * "star" on top of that is noise.
   */
  const requiredMark = (
    <span className="ec-required" aria-hidden="true">
      *
    </span>
  );

  const problem = (field: string): React.JSX.Element | null => {
    const found = problemFor(field);
    return found === undefined ? null : (
      <p className="ec-problem" role="alert">
        {found.message}
      </p>
    );
  };

  return (
    // ec-shell is the container query's subject; ec-root is what it sizes (see styles.ts).
    <div className="ec-shell">
      <div className="ec-root" data-preview={showPreview ? 'on' : 'off'}>
        <form className="ec-fields" onSubmit={submit} noValidate>
          {/* Grouped the way a calendar app groups them — what it is, when it is, who is coming,
              what warns you, and the details — rather than fourteen fields in one column. The
              legends are real ones: a screen reader announces which group a field is in. */}
          <fieldset className="ec-group">
            <legend>Event</legend>
            <div className="ec-field">
              <label htmlFor="ec-title">Title{requiredMark}</label>
              <input
                id="ec-title"
                type="text"
                required
                maxLength={LIMITS.title}
                value={draft.title}
                placeholder="Team standup"
                onChange={(event) => dispatch({ type: 'set-title', value: event.target.value })}
              />
              {problem('title')}
            </div>

            <div className="ec-field">
              <label htmlFor="ec-location">Location</label>
              <input
                id="ec-location"
                type="text"
                maxLength={LIMITS.location}
                value={draft.location ?? ''}
                onChange={(event) => dispatch({ type: 'set-location', value: event.target.value })}
              />
            </div>
          </fieldset>

          <fieldset className="ec-group">
            <legend>When</legend>
            <label className="ec-inline ec-switch">
              <input
                type="checkbox"
                checked={allDay}
                onChange={(event) => dispatch({ type: 'set-all-day', value: event.target.checked })}
              />
              All-day
            </label>

            {/* Each side of the event — its date, its time, and the zone that time is in —
                is one wrapping unit. Three-across where there is room, then date and time with
                the zone beneath, then one field per line on a phone. Keeping the zone inside the
                side it belongs to is the whole point: a lone zone select under both rows cannot
                say which time it applies to, and once the two sides can differ it has to. */}
            <div className="ec-row">
              <div className="ec-pair">
                <div className="ec-field">
                  <label htmlFor="ec-start-date">Starts{requiredMark}</label>
                  <input
                    id="ec-start-date"
                    type="date"
                    required
                    value={startDate}
                    onChange={(event) =>
                      dispatch({ type: 'set-start-date', value: event.target.value })
                    }
                  />
                </div>
                {!allDay && (
                  <div className="ec-field">
                    <label htmlFor="ec-start-time">Start time{requiredMark}</label>
                    <input
                      id="ec-start-time"
                      type="time"
                      required
                      value={startTime}
                      onChange={(event) =>
                        dispatch({ type: 'set-start-time', value: event.target.value })
                      }
                    />
                  </div>
                )}
                {!allDay && (
                  <div className="ec-field">
                    <label htmlFor="ec-zone">{splitZones ? 'Start time zone' : 'Time zone'}</label>
                    <select
                      id="ec-zone"
                      value={creator.state.timeZone ?? ''}
                      onChange={(event) =>
                        dispatch({
                          type: 'set-time-zone',
                          value: event.target.value === '' ? undefined : event.target.value,
                        })
                      }
                    >
                      {zoneOptions}
                    </select>
                  </div>
                )}
              </div>
              <div className="ec-pair">
                <div className="ec-field">
                  <label htmlFor="ec-end-date">Ends{requiredMark}</label>
                  <input
                    id="ec-end-date"
                    type="date"
                    required
                    value={endDate}
                    onChange={(event) =>
                      dispatch({ type: 'set-end-date', value: event.target.value })
                    }
                  />
                </div>
                {!allDay && (
                  <div className="ec-field">
                    <label htmlFor="ec-end-time">End time{requiredMark}</label>
                    <input
                      id="ec-end-time"
                      type="time"
                      required
                      value={endTime}
                      onChange={(event) =>
                        dispatch({ type: 'set-end-time', value: event.target.value })
                      }
                    />
                  </div>
                )}
                {/* The end's zone sits under the end, and only exists once the two differ. The
                    slot is left empty otherwise rather than filled with a duplicate of the start
                    zone, which would imply two independent controls where there is one. */}
                {!allDay && splitZones && (
                  <div className="ec-field">
                    <label htmlFor="ec-end-zone">End time zone</label>
                    <select
                      id="ec-end-zone"
                      value={endZone ?? ''}
                      onChange={(event) =>
                        dispatch({
                          type: 'set-end-time-zone',
                          value: event.target.value === '' ? undefined : event.target.value,
                        })
                      }
                    >
                      {zoneOptions}
                    </select>
                  </div>
                )}
              </div>
            </div>
            {problem('start')}
            {problem('end')}

            {/* The other way round from the two dates above: say how long it lasts and the end
                follows. Most events are known as "half an hour", not as a time to stop, and the
                two stay in step either way — editing the end rewrites these.

                A real fieldset, because three boxes that only mean something together should be
                announced as one thing; the legend is the label the "Duration" heading would be. */}
            <fieldset className="ec-duration">
              <legend>Duration</legend>
              <div className="ec-inline">
                {DURATION_UNITS.filter((unit) => !allDay || unit.key === 'days').map((unit) => (
                  <div className="ec-field ec-duration-part" key={unit.key}>
                    <label htmlFor={`ec-duration-${unit.key}`}>{unit.label}</label>
                    <input
                      id={`ec-duration-${unit.key}`}
                      type="number"
                      min={0}
                      inputMode="numeric"
                      value={durationFields[unit.key]}
                      onChange={(event) => setDurationField(unit.key, event.target.value)}
                      // Leaving settles the boxes on the draft's own split, which is where the
                      // carry becomes visible: 26 in Hours comes back as 1 day, 2 hours.
                      onBlur={() => setTypedDuration(null)}
                    />
                  </div>
                ))}
              </div>
            </fieldset>

            {!allDay && (
              <>
                <p className="ec-hint">
                  {creator.state.timeZone === undefined
                    ? 'Opens at this clock time wherever the event is added.'
                    : splitZones
                      ? 'The start and end each carry their own zone, so a flight that leaves at 15:00 in one place and lands at 11:00 in another reads correctly in a calendar.'
                      : `Everyone sees this time in ${creator.state.timeZone}${
                          creator.state.timeZone === browserZone ? ' — your time zone' : ''
                        }.`}
                </p>

                {/* DTSTART and DTEND each carry their own TZID, so an event may legitimately end
                    in a different zone from the one it started in — a flight is the whole reason
                    the parameter is per-property. Behind a checkbox because it is wrong for
                    almost every other event, and only offered once a start zone exists: without
                    one the times are floating, and there is nothing for the end to differ from. */}
                {creator.state.timeZone !== undefined && draft.end !== undefined && (
                  <label className="ec-inline ec-switch">
                    <input
                      type="checkbox"
                      checked={splitZones}
                      onChange={(event) => {
                        setSplitZones(event.target.checked);
                        if (!event.target.checked)
                          dispatch({ type: 'set-end-time-zone', value: creator.state.timeZone });
                      }}
                    />
                    Ends in a different time zone
                  </label>
                )}
              </>
            )}

            <div className="ec-field">
              <label htmlFor="ec-repeat">Repeat</label>
              <select
                id="ec-repeat"
                value={repeatPreset}
                onChange={(event) => {
                  const id = event.target.value;
                  setCustomRepeat(id === 'custom');
                  if (id === 'never') return setRecurrence(undefined);
                  const preset = REPEAT_PRESETS.find((entry) => entry.id === id);
                  if (preset === undefined || !('frequency' in preset)) {
                    // Custom starts from whatever is already set, so switching to it never
                    // silently rewrites a rule the user built.
                    return setRecurrence(recurrence ?? { frequency: 'weekly' });
                  }
                  setRecurrence({
                    ...withoutEnd(recurrence ?? { frequency: preset.frequency }),
                    frequency: preset.frequency,
                    ...(preset.interval === 1 ? {} : { interval: preset.interval }),
                    ...(recurrence?.count === undefined ? {} : { count: recurrence.count }),
                    ...(recurrence?.until === undefined ? {} : { until: recurrence.until }),
                  });
                }}
              >
                {REPEAT_PRESETS.map((preset) => (
                  <option key={preset.id} value={preset.id}>
                    {preset.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Custom is the only place a frequency and an interval need their own controls; the
              presets above cover the cases that would otherwise send someone here. */}
            {recurrence !== undefined && repeatPreset === 'custom' && (
              <div className="ec-row">
                <div className="ec-field">
                  <label htmlFor="ec-repeat-frequency">Frequency</label>
                  <select
                    id="ec-repeat-frequency"
                    value={recurrence.frequency}
                    onChange={(event) =>
                      setRecurrence({
                        ...recurrence,
                        frequency: event.target.value as RecurrenceFrequency,
                      })
                    }
                  >
                    {FREQUENCIES.map((frequency) => (
                      <option key={frequency} value={frequency}>
                        {frequency[0]?.toUpperCase()}
                        {frequency.slice(1)}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="ec-field">
                  <label htmlFor="ec-repeat-interval">Every</label>
                  <div className="ec-inline">
                    <input
                      id="ec-repeat-interval"
                      type="number"
                      min={1}
                      max={LIMITS.recurrenceInterval}
                      inputMode="numeric"
                      value={recurrence.interval ?? 1}
                      onChange={(event) =>
                        setRecurrence({
                          ...recurrence,
                          // Empty or nonsense means 1 rather than an error: the field has a
                          // sensible reading of "blank", and RRULE omits INTERVAL=1 anyway.
                          interval: Math.max(1, Math.trunc(Number(event.target.value) || 1)),
                        })
                      }
                    />
                    <span className="ec-unit">{INTERVAL_UNIT[recurrence.frequency]}</span>
                  </div>
                  {problem('recurrence.interval')}
                </div>
              </div>
            )}

            {recurrence !== undefined && (
              <>
                <div className="ec-field">
                  {/* "End repeat" is Apple's wording, and it avoids colliding with the event's own
                    Ends field a few rows up — two controls labelled "Ends" is a real ambiguity,
                    for a screen reader reading them in sequence and for everyone else. */}
                  <label htmlFor="ec-repeat-ends">End repeat</label>
                  <select
                    id="ec-repeat-ends"
                    value={repeatEnd}
                    onChange={(event) => {
                      const next = event.target.value as RepeatEnd;
                      // COUNT and UNTIL are mutually exclusive in RFC 5545, and the validator
                      // rejects both together — so switching modes drops the other one here
                      // rather than leaving the form in a state it can't export.
                      if (next === 'never') setRecurrence(withoutEnd(recurrence));
                      else if (next === 'count')
                        setRecurrence({ ...withoutEnd(recurrence), count: 10 });
                      else setRecurrence({ ...withoutEnd(recurrence), until: startDate });
                    }}
                  >
                    <option value="never">Never</option>
                    <option value="count">After a number of times</option>
                    <option value="until">On a date</option>
                  </select>
                </div>

                {repeatEnd === 'count' && (
                  <div className="ec-field">
                    <label htmlFor="ec-repeat-count">Number of times</label>
                    <input
                      id="ec-repeat-count"
                      type="number"
                      min={1}
                      max={LIMITS.recurrenceCount}
                      inputMode="numeric"
                      value={recurrence.count ?? 1}
                      onChange={(event) =>
                        setRecurrence({
                          ...withoutEnd(recurrence),
                          count: Math.max(1, Math.trunc(Number(event.target.value) || 1)),
                        })
                      }
                    />
                    {problem('recurrence.count')}
                  </div>
                )}

                {repeatEnd === 'until' && (
                  <div className="ec-field">
                    <label htmlFor="ec-repeat-until">Last date</label>
                    <input
                      id="ec-repeat-until"
                      type="date"
                      value={recurrence.until ?? ''}
                      onChange={(event) =>
                        setRecurrence({ ...withoutEnd(recurrence), until: event.target.value })
                      }
                    />
                    {problem('recurrence.until')}
                  </div>
                )}
                {problem('recurrence')}
                <p className="ec-hint">{repeatSummary(recurrence)}</p>
              </>
            )}
          </fieldset>

          <fieldset className="ec-group">
            <legend>Invitees</legend>
            <div className="ec-field">
              <label htmlFor="ec-attendee">Add an invitee</label>
              <div className="ec-inline">
                <input
                  id="ec-attendee"
                  type="email"
                  value={attendee}
                  placeholder="name@example.com"
                  onChange={(event) => setAttendee(event.target.value)}
                  onKeyDown={(event) => {
                    if (event.key === 'Enter') {
                      event.preventDefault();
                      addAttendee();
                    }
                  }}
                />
                <button type="button" className="ec-chip" onClick={addAttendee}>
                  Add
                </button>
              </div>
              {(draft.attendees ?? []).map((guest, index) => (
                <div className="ec-attendee" key={`${guest.email}-${index}`}>
                  <span>{guest.email}</span>
                  <button
                    type="button"
                    className="ec-remove"
                    aria-label={`Remove ${guest.email}`}
                    onClick={() => dispatch({ type: 'remove-attendee', index })}
                  >
                    Remove
                  </button>
                </div>
              ))}
              {(draft.attendees ?? []).map((_, index) => problem(`attendees[${index}].email`))}
            </div>
          </fieldset>

          <fieldset className="ec-group">
            <legend>Alerts</legend>
            {alertRows.map((minutes, index) => (
              <div className="ec-field" key={`alert-${index}`}>
                <label htmlFor={`ec-alert-${index}`}>{alertRowLabel(index)}</label>
                <select
                  id={`ec-alert-${index}`}
                  value={minutes ?? ''}
                  onChange={(event) =>
                    dispatch({
                      type: 'set-reminder',
                      index,
                      minutes: event.target.value === '' ? undefined : Number(event.target.value),
                    })
                  }
                >
                  <option value="">None</option>
                  {ALERT_CHOICES.map((choice) => (
                    <option key={choice} value={choice}>
                      {alertLabel(choice)}
                    </option>
                  ))}
                </select>
              </div>
            ))}

            <div className="ec-field">
              {/* TRANSP, which decides whether the event blocks your free/busy or merely sits in
                the calendar. Apple and Outlook both call it "Show as". */}
              <label htmlFor="ec-show-as">Show as</label>
              <select
                id="ec-show-as"
                value={draft.showAs ?? 'busy'}
                onChange={(event) =>
                  dispatch({ type: 'set-show-as', value: event.target.value as EventShowAs })
                }
              >
                <option value="busy">Busy</option>
                <option value="free">Free</option>
              </select>
            </div>
          </fieldset>

          <fieldset className="ec-group">
            <legend>Details</legend>
            <div className="ec-field">
              <label htmlFor="ec-url">URL</label>
              <input
                id="ec-url"
                type="url"
                maxLength={LIMITS.url}
                inputMode="url"
                value={draft.url ?? ''}
                placeholder="https://…"
                onChange={(event) => dispatch({ type: 'set-url', value: event.target.value })}
              />
              {problem('url')}
            </div>

            <div className="ec-field">
              <label htmlFor="ec-description">Notes</label>
              <textarea
                id="ec-description"
                maxLength={LIMITS.description}
                value={draft.description ?? ''}
                onChange={(event) =>
                  dispatch({ type: 'set-description', value: event.target.value })
                }
              />
            </div>
          </fieldset>

          <fieldset className="ec-group">
            <legend>Download</legend>
            <div className="ec-field">
              <label htmlFor="ec-format">Download as</label>
              <select
                id="ec-format"
                value={creator.state.formatId}
                onChange={(event) =>
                  dispatch({ type: 'set-format', value: event.target.value as EventFormatId })
                }
              >
                {creator.formats.map((format) => (
                  <option key={format.id} value={format.id}>
                    {format.label}
                  </option>
                ))}
              </select>
            </div>

            {/* The whole event in one line, right where the decision to download is made. Every
                field is plausible on its own; it is the combination people get wrong. */}
            <p className="ec-recap">{eventRecap(draft)}</p>

            {/* The key sits here rather than above the first field: the mark only matters at the
                moment of download, and a form that opens with a note about asterisks reads as
                more work than it is. */}
            <p className="ec-hint">
              <span className="ec-required" aria-hidden="true">
                *
              </span>{' '}
              Needed before this event can be downloaded.
            </p>

            <div className="ec-actions">
              <button type="submit" className="ec-button">
                Download event
              </button>
              <button
                type="button"
                className="ec-button ec-secondary"
                onClick={async () => {
                  const result = creator.requestExport();
                  if (!result.ok) return;
                  setCopied(await copyExport(result.export));
                }}
              >
                {copied ? 'Copied' : 'Copy text'}
              </button>
            </div>
          </fieldset>
        </form>

        <aside className="ec-side">
          {props.propose !== undefined && (
            <DescribeEvent
              propose={props.propose}
              onDraft={(value) => dispatch({ type: 'load', value })}
            />
          )}
          <div className="ec-panel">
            <h2>Add straight to a calendar</h2>
            <div className="ec-links">
              {creator.links.map((link) => (
                <a key={link.provider} href={link.url} target="_blank" rel="noreferrer noopener">
                  {link.label}
                </a>
              ))}
            </div>
          </div>
          {showPreview && (
            <div className="ec-panel">
              {/* h2, not h3: a host page's own h1 is the only heading above this, and skipping a
                  level is a real accessibility failure — the site scored 98 on it. Two panels at
                  the same level is also what they are. */}
              <h2>
                {creator.formats.find((format) => format.id === creator.state.formatId)?.label}{' '}
                preview
              </h2>
              <pre className="ec-preview">
                {creator.preview ?? 'Fill in the event to see the file.'}
              </pre>
            </div>
          )}
        </aside>
      </div>
    </div>
  );
}
